\set ON_ERROR_STOP on
begin;
create function pg_temp.assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL %',label;end if;end$$;
create function pg_temp.reject(q text,code text) returns void language plpgsql as $$begin begin execute q;exception when others then if sqlstate=code then return;end if;raise;end;raise exception 'FAIL accepted %',q;end$$;
insert into auth.users(id,email) values('64000000-0000-4000-8000-000000000001','detail-pub-sql-owner@example.test'),('64000000-0000-4000-8000-000000000009','detail-pub-sql-foreign@example.test');
select public.create_staging_business('64000000-0000-4000-8000-000000000001','64000000-0000-4000-8000-000000000002','Detailing','detail-pub-sql','UTC','USD','AUTO_DETAILING','detail-pub-business-sql-001');
select public.create_auto_detailing_offer('64000000-0000-4000-8000-000000000001','64000000-0000-4000-8000-000000000002','64000000-0000-4000-8000-000000000004','{"name":"Detail menu","description":"","currency":"USD","durationMinutes":120,"packages":[{"id":"basic","label":"Basic","amount":12500}],"vehicles":[{"id":"sedan","label":"Sedan","multiplierBp":10000}],"addons":[],"locations":[],"idempotencyKey":"detail-pub-offer-sql-001"}');
select public.create_auto_detailing_offer_scheduling('64000000-0000-4000-8000-000000000001','64000000-0000-4000-8000-000000000002','64000000-0000-4000-8000-000000000004','UTC','[{"weekday":1,"startMinute":540,"endMinute":1020,"capacity":1}]',0,30,30,'detail-pub-schedule-sql-001');
create function pg_temp.save(a uuid default '64000000-0000-4000-8000-000000000001',expected bigint default 0,p_name text default 'Published menu') returns jsonb language sql as $$select public.save_detailing_draft(a,'64000000-0000-4000-8000-000000000002','64000000-0000-4000-8000-000000000003','64000000-0000-4000-8000-000000000004',expected,p_name,'#4f46e5','stacked')$$;
create function pg_temp.publish(expected bigint default 1,origins jsonb default '["https://checkout.example.test"]') returns jsonb language sql as $$select public.publish_detailing_draft('64000000-0000-4000-8000-000000000001','64000000-0000-4000-8000-000000000002','64000000-0000-4000-8000-000000000003',expected,'64000000-0000-4000-8000-000000000005','64000000-0000-4000-8000-000000000006',origins)$$;
select pg_temp.assert((select bool_and(relrowsecurity and relforcerowsecurity) from pg_class where oid in('public.detailing_drafts'::regclass,'public.detailing_publications'::regclass)),'private forced RLS');
select pg_temp.assert(not has_table_privilege('service_role','public.detailing_drafts','SELECT') and not has_table_privilege('service_role','public.detailing_publications','INSERT'),'no direct grants');
select pg_temp.assert((select bool_and(prosecdef and proconfig=array['search_path=pg_catalog']) from pg_proc where oid in('public.save_detailing_draft(uuid,uuid,uuid,uuid,bigint,text,text,text)'::regprocedure,'public.get_detailing_draft(uuid,uuid,uuid)'::regprocedure,'public.publish_detailing_draft(uuid,uuid,uuid,bigint,uuid,uuid,jsonb)'::regprocedure,'public.issue_detailing_flow_session(uuid,text,text,jsonb)'::regprocedure,'public.resolve_detailing_flow_session(text,text,jsonb)'::regprocedure)),'fixed definer RPCs');
set local role anon;select pg_temp.reject($q$select pg_temp.save()$q$,'42501');select pg_temp.reject($q$select public.issue_detailing_flow_session('64000000-0000-4000-8000-000000000006',repeat('a',64),'https://checkout.example.test','["https://checkout.example.test"]')$q$,'42501');reset role;
set local role authenticated;select pg_temp.reject($q$select pg_temp.save()$q$,'42501');select pg_temp.reject($q$select * from public.detailing_drafts$q$,'42501');reset role;
select pg_temp.reject($q$select pg_temp.save(a=>'64000000-0000-4000-8000-000000000009')$q$,'42501');select pg_temp.reject($q$select pg_temp.save(expected=>-1)$q$,'22023');select pg_temp.reject($q$select pg_temp.save(p_name=>' padded ')$q$,'22023');
set local role service_role;select pg_temp.assert(pg_temp.save()->>'revision'='1','first save');select pg_temp.reject($q$select pg_temp.save()$q$,'23505');select pg_temp.assert(public.get_detailing_draft('64000000-0000-4000-8000-000000000001','64000000-0000-4000-8000-000000000002','64000000-0000-4000-8000-000000000003')->>'name'='Published menu','fresh owner read');reset role;
select pg_temp.reject($q$select pg_temp.publish(expected=>2)$q$,'40001');select pg_temp.reject($q$select pg_temp.publish(origins=>'["https://checkout.example.test/path"]')$q$,'22023');
-- Injected publication-ledger failure rolls back flow, version, private binding and installation.
create function pg_temp.fail_detailing_publication() returns trigger language plpgsql as $$begin if new.tenant_id='64000000-0000-4000-8000-000000000002' then raise exception 'fixture failure';end if;return new;end$$;
create trigger fixture_detailing_publication before insert on public.detailing_publications for each row execute function pg_temp.fail_detailing_publication();select pg_temp.reject($q$select pg_temp.publish()$q$,'P0001');drop trigger fixture_detailing_publication on public.detailing_publications;
