set local role service_role;select pg_temp.assert(pg_temp.publish()->>'renderSchemaVersion'='7','explicit7 publication');select pg_temp.assert(pg_temp.publish()->>'replayed'='true','same revision exact replay');select pg_temp.assert(public.owner_detailing_publication('64000000-0000-4000-8000-000000000001','64000000-0000-4000-8000-000000000002','64000000-0000-4000-8000-000000000003','["https://checkout.example.test"]')->>'versionId'='64000000-0000-4000-8000-000000000005','authoritative current recovery');
select pg_temp.assert(public.issue_detailing_flow_session('64000000-0000-4000-8000-000000000006',repeat('a',64),'https://checkout.example.test','["https://checkout.example.test"]')#>>'{render,submissionMode}'='detailing_quote','dedicated canonical session');
select pg_temp.reject($q$select public.resolve_detailing_flow_session(repeat('a',64),'https://foreign.example.test','["https://checkout.example.test"]')$q$,'42501');select pg_temp.reject($q$select public.issue_flow_session('64000000-0000-4000-8000-000000000006',repeat('b',64),'https://checkout.example.test')$q$,'0A000');reset role;
select pg_temp.reject($q$update public.detailing_publications set catalog_snapshot='{}' where tenant_id='64000000-0000-4000-8000-000000000002'$q$,'55000');select pg_temp.reject($q$update public.flow_versions set detailing_snapshot='{}' where tenant_id='64000000-0000-4000-8000-000000000002'$q$,'55000');
update public.availability_rules set capacity=2 where tenant_id='64000000-0000-4000-8000-000000000002';select pg_temp.reject($q$select public.resolve_detailing_flow_session(repeat('a',64),'https://checkout.example.test','["https://checkout.example.test"]')$q$,'40001');update public.availability_rules set capacity=1 where tenant_id='64000000-0000-4000-8000-000000000002';
