select pg_temp.assert(pg_temp.save(expected=>1,p_name=>'Later unpublished name')->>'revision'='2','explicit draft revision update');select pg_temp.reject($q$select public.owner_detailing_publication('64000000-0000-4000-8000-000000000001','64000000-0000-4000-8000-000000000002','64000000-0000-4000-8000-000000000003','["https://checkout.example.test"]')$q$,'P0002');select pg_temp.assert(public.resolve_detailing_flow_session(repeat('a',64),'https://checkout.example.test','["https://checkout.example.test"]')#>>'{render,publication,name}'='Published menu','issued session pinned old metadata');
update public.flow_sessions set expires_at=clock_timestamp()-interval '1 second' where tenant_id='64000000-0000-4000-8000-000000000002';select pg_temp.reject($q$select public.resolve_detailing_flow_session(repeat('a',64),'https://checkout.example.test','["https://checkout.example.test"]')$q$,'42501');
select pg_temp.assert((select count(*)=0 from public.bookings where tenant_id='64000000-0000-4000-8000-000000000002') and(select count(*)=0 from public.payments where tenant_id='64000000-0000-4000-8000-000000000002') and(select count(*)=0 from public.capacity_holds where tenant_id='64000000-0000-4000-8000-000000000002') and(select count(*)=0 from public.flow_requests where tenant_id='64000000-0000-4000-8000-000000000002'),'no request/financial writes');
